import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const source=path=>readFileSync(path,'utf8');
const schema=source('supabase/migrations/20261123220000_dine_lite_pos_table_qr_kds.sql');
const publicApi=source('app/api/dine/table/route.ts');
const privateApi=source('app/api/dine/staff/route.ts');
const adminApi=source('app/api/admin/dine/route.ts');
const guest=source('app/dine/table/page.tsx');
const kitchen=source('app/dine/kitchen/page.tsx');
const admin=source('app/admin/dine/page.tsx');
const status=source('app/api/dine/table/order/route.ts');
const qr=source('app/lib/dine-qr-code.ts');
const dine=source('app/dine/page.tsx');
for(const value of ['dine_restaurant_staff','dine_table_orders','dine_table_order_events']){
 assert(schema.includes('create table if not exists public.'+value),'Missing private Lite POS table '+value);
 assert(schema.includes("alter table public.%I enable row level security"),'Missing RLS');
 assert(schema.includes("'"+value+"'"),'Missing deny direct public table grants');
}
assert(schema.includes('qr_order_enabled boolean not null default false'),'QR pilot must be OFF by default');
assert(schema.includes('qr_token uuid not null default gen_random_uuid()'),'Table QR tokens must be unguessable');
assert(schema.includes("grant execute on function public.create_dine_table_order("),'Server RPC must be callable by service role');
assert(schema.includes('revoke all on function public.create_dine_table_order('),'No direct public order RPC execution');
assert(schema.includes('pg_advisory_xact_lock'),'Guest rate limiting must be atomic for same-table requests');
assert(schema.includes('idempotency_key'),'Every QR request must be safe to retry without duplicate cooking');
assert(schema.includes("'PENDING_APPROVAL'"),'Guest requests cannot auto-create KOT');
assert(schema.includes('v_status:=\'PENDING_APPROVAL\''),'Guest submissions must await staff approval');
assert(schema.includes("v_origin:='STAFF_TABLE';v_status:='ACCEPTED'"),'Waiter submissions require authenticated staff');
assert(schema.includes("payment_status text not null default 'NOT_COLLECTED'"),'No fake payment confirmation');
assert(publicApi.includes(".eq('fssai_verified',true)")||publicApi.includes("!restaurant.fssai_verified"),'Public menus must be verified');
assert(publicApi.includes(".eq('qr_token',token)"),'Public menu access must verify specific QR table token');
assert(publicApi.includes("dineUser(request)"),'Staff submitted requests must require signed-in user');
assert(publicApi.includes("db.rpc('create_dine_table_order'"),'Order prices must be computed atomically on backend');
assert(publicApi.includes('fingerprint(request)'),'Guest order spam must be throttled');
assert(!publicApi.includes('razorpay'),'No payment capture from an unready QR pilot');
assert(privateApi.includes('dineStaffAccess(request'),'Every kitchen action must enforce restaurant membership');
assert(privateApi.includes(".eq('restaurant_id',restaurantId)"),'Kitchen updates must be tenant-scoped');
assert(privateApi.includes("db.rpc('confirm_dine_booking'"),'Prebooking confirmation must use existing collision-safe RPC');
assert(privateApi.includes('PENDING_APPROVAL:[\'ACCEPTED\',\'REJECTED\']'),'QR KOT requires staff review');
assert(status.includes(".eq('idempotency_key',key)"),'Guest status must require a private receipt token');
assert(!status.includes('contact_phone'),'Public guest order receipt must not reveal phone numbers');
assert(adminApi.includes("getRuntimeEnvValue('DINE_OPERATIONS_APPROVED')"),'Restaurant pilot activation requires food compliance');
assert(adminApi.includes("qrPilot"),'Only Zeshu Admin can enable QR pilot after review');
assert(adminApi.includes("staffAssign"),'Restaurant staff must be explicitly enrolled');
assert(adminApi.includes("rotateTableQr"),'Stolen QR tokens must be revocable');
assert(admin.includes("Approve staff member"),'Admin UI must expose staffed onboarding');
assert(admin.includes("Review/Enable"),'Admin UI must expose manual pilot activation');
assert(guest.includes("Request order"),'Guest UX must never assert a paid/accepted order prematurely');
assert(guest.includes("PENDING_APPROVAL"),'Guest must see pending status');
assert(guest.includes("Pay at the restaurant"),'Guest must know how to settle the bill');
assert(kitchen.includes('dine-qr-code'),'Local QR generation must not call third party QR provider');
assert(kitchen.includes('Print/PDF')&&kitchen.includes('Print KOT'),'Kitchen must support standee & ticket printing');
assert(kitchen.includes('Delivery is held pending partner readiness'),'Delivery must stay off without dispatch providers');
assert(kitchen.includes('Waiter-assisted order'),'Human ordering fallback must remain available');
assert(qr.includes('Project Nayuki')&&qr.includes('MIT License'),'Local QR generator must retain license');
assert(dine.includes('href="/dine/kitchen"'),'Restaurant dashboard must be reachable from Dine');
console.log('PASS: Dine Lite POS private access, staff approval, QR tokens, anti-spam, idempotent KOT, printable standees and held delivery.');
